-- Tables   : club, configuration, correspondant, departement, disponible, division, equipe, import_rencontre_fichier, ja, laposte, messagerie, nomination, region, rencontre, salle, utilisateur

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ── club ──
DROP TABLE IF EXISTS `club`;
CREATE TABLE `club` (
  `Id_Club` int(11) NOT NULL AUTO_INCREMENT,
  `Nom` varchar(50) NOT NULL,
  PRIMARY KEY (`Id_Club`),
  UNIQUE KEY `Nom` (`Nom`)
) ENGINE=InnoDB AUTO_INCREMENT=9760464 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── configuration ──
DROP TABLE IF EXISTS `configuration`;
CREATE TABLE `configuration` (
  `cle` varchar(50) NOT NULL,
  `valeur` text NOT NULL,
  `libelle` varchar(255) NOT NULL DEFAULT '',
  `description` text DEFAULT NULL,
  PRIMARY KEY (`cle`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── correspondant ──
DROP TABLE IF EXISTS `correspondant`;
CREATE TABLE `correspondant` (
  `Id_Correspondant` int(11) NOT NULL AUTO_INCREMENT,
  `Id_Club` int(11) NOT NULL,
  `Nom` varchar(100) NOT NULL,
  `Email` varchar(100) DEFAULT NULL,
  `Telephone` varchar(20) DEFAULT NULL,
  `Fonction` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`Id_Correspondant`),
  KEY `fk_correspondant_club` (`Id_Club`),
  CONSTRAINT `fk_correspondant_club` FOREIGN KEY (`Id_Club`) REFERENCES `club` (`Id_Club`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7650113 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── departement ──
DROP TABLE IF EXISTS `departement`;
CREATE TABLE `departement` (
  `code` varchar(3) NOT NULL,
  `nom` varchar(255) NOT NULL,
  `code_region` varchar(2) DEFAULT NULL,
  PRIMARY KEY (`code`),
  KEY `Departement_Region` (`code_region`),
  CONSTRAINT `Departement_Region` FOREIGN KEY (`code_region`) REFERENCES `region` (`code`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── disponible ──
DROP TABLE IF EXISTS `disponible`;
CREATE TABLE `disponible` (
  `Id_Disponible` int(11) NOT NULL AUTO_INCREMENT,
  `Id_JA` int(11) DEFAULT NULL,
  `Reponse` enum('O','P','N') DEFAULT 'N',
  `DateReponse` date DEFAULT NULL,
  `Id_Rencontre` int(11) DEFAULT NULL,
  `Preference` tinyint(4) DEFAULT NULL COMMENT '1=faible … 10=forte',
  `DateCompetition` date DEFAULT NULL,
  PRIMARY KEY (`Id_Disponible`),
  UNIQUE KEY `uq_dispo` (`Id_JA`,`Id_Rencontre`),
  KEY `Id_Rencontre` (`Id_Rencontre`),
  CONSTRAINT `disponible_ibfk_1` FOREIGN KEY (`Id_Rencontre`) REFERENCES `rencontre` (`Id_Rencontre`),
  CONSTRAINT `fk_disponible_ja` FOREIGN KEY (`Id_JA`) REFERENCES `ja` (`Id_JA`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=478 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── division ──
DROP TABLE IF EXISTS `division`;
CREATE TABLE `division` (
  `Id_Division` int(11) NOT NULL AUTO_INCREMENT,
  `Division` varchar(50) DEFAULT NULL,
  `Nom` varchar(100) DEFAULT NULL,
  `Color` varchar(7) NOT NULL,
  `ArbitrageObligatoire` tinyint(1) NOT NULL DEFAULT 1,
  `Ord` int(11) DEFAULT NULL,
  PRIMARY KEY (`Id_Division`),
  UNIQUE KEY `Nom` (`Nom`),
  UNIQUE KEY `Ord` (`Ord`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── equipe ──
DROP TABLE IF EXISTS `equipe`;
CREATE TABLE `equipe` (
  `Id_Equipe` int(11) NOT NULL AUTO_INCREMENT,
  `Nom` varchar(100) DEFAULT NULL,
  `Id_Division` int(11) DEFAULT NULL,
  `Id_Club` int(11) NOT NULL,
  PRIMARY KEY (`Id_Equipe`),
  UNIQUE KEY `uq_equipe_nom_div` (`Nom`(80),`Id_Division`),
  KEY `fk_equipe_division` (`Id_Division`),
  KEY `fk_equipe_club` (`Id_Club`),
  CONSTRAINT `fk_equipe_club` FOREIGN KEY (`Id_Club`) REFERENCES `club` (`Id_Club`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_equipe_division` FOREIGN KEY (`Id_Division`) REFERENCES `division` (`Id_Division`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=115 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── import_rencontre_fichier ──
DROP TABLE IF EXISTS `import_rencontre_fichier`;
CREATE TABLE `import_rencontre_fichier` (
  `Nom` varchar(255) NOT NULL,
  `DateImport` datetime NOT NULL,
  `Utilisateur` varchar(150) DEFAULT NULL,
  PRIMARY KEY (`Nom`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── ja ──
DROP TABLE IF EXISTS `ja`;
CREATE TABLE `ja` (
  `Id_JA` int(11) NOT NULL AUTO_INCREMENT,
  `Nom` varchar(50) DEFAULT NULL,
  `Prenom` varchar(50) DEFAULT NULL,
  `Email` varchar(100) DEFAULT NULL,
  `Telephone` varchar(20) DEFAULT NULL,
  `Grade` varchar(3) DEFAULT NULL,
  `Actif` tinyint(1) DEFAULT 1,
  `Id_Club` int(11) DEFAULT NULL,
  `DistanceMaxKm` int(11) DEFAULT NULL,
  `Defiscalisation` tinyint(1) NOT NULL DEFAULT 0,
  `Note` text DEFAULT NULL,
  `Id_LaPoste` int(11) DEFAULT NULL,
  `Cp` varchar(10) DEFAULT NULL,
  `Ville` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`Id_JA`),
  KEY `fk_ja_club` (`Id_Club`),
  KEY `fk_ja_laposte` (`Id_LaPoste`),
  CONSTRAINT `fk_ja_club` FOREIGN KEY (`Id_Club`) REFERENCES `club` (`Id_Club`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_ja_laposte` FOREIGN KEY (`Id_LaPoste`) REFERENCES `laposte` (`Id_LaPoste`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9744891 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── laposte ──
DROP TABLE IF EXISTS `laposte`;
CREATE TABLE `laposte` (
  `Id_LaPoste` int(11) NOT NULL AUTO_INCREMENT,
  `Nom` varchar(100) NOT NULL,
  `CodePostal` varchar(5) NOT NULL,
  `Latitude` decimal(10,6) NOT NULL,
  `Longitude` decimal(10,6) NOT NULL,
  PRIMARY KEY (`Id_LaPoste`)
) ENGINE=InnoDB AUTO_INCREMENT=98902 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── messagerie ──
DROP TABLE IF EXISTS `messagerie`;
CREATE TABLE `messagerie` (
  `Id_Messagerie` int(11) NOT NULL AUTO_INCREMENT,
  `Id_Utilisateur` int(11) NOT NULL DEFAULT 0,
  `Type` enum('Disponibilites','Convocation','Rappel dispo','Liste nomination') NOT NULL DEFAULT 'Disponibilites',
  `Sujet` varchar(150) NOT NULL,
  `Message` text NOT NULL,
  PRIMARY KEY (`Id_Messagerie`),
  KEY `Id_Utilisateur` (`Id_Utilisateur`)
) ENGINE=MyISAM AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── nomination ──
DROP TABLE IF EXISTS `nomination`;
CREATE TABLE `nomination` (
  `id_Nomination` int(11) NOT NULL AUTO_INCREMENT,
  `Id_JA` int(11) DEFAULT NULL,
  `Id_Rencontre` int(11) DEFAULT NULL,
  `Peage` decimal(8,2) NOT NULL DEFAULT 0.00,
  `Kilometre` int(11) NOT NULL DEFAULT 0,
  `RapportAccueil` text DEFAULT NULL,
  `RapportEquipements` text DEFAULT NULL,
  `DateSaisie` date NOT NULL,
  `DateNomination` date NOT NULL,
  `Valide` tinyint(1) NOT NULL DEFAULT 0,
  `EmailEnvoye` tinyint(1) NOT NULL DEFAULT 0,
  `Peages` decimal(8,2) DEFAULT NULL,
  `Kilometres` int(11) DEFAULT NULL,
  PRIMARY KEY (`id_Nomination`),
  UNIQUE KEY `uq_ja_renc` (`Id_JA`,`Id_Rencontre`),
  KEY `fk_nomination_rencontre` (`Id_Rencontre`),
  CONSTRAINT `fk_nomination_ja` FOREIGN KEY (`Id_JA`) REFERENCES `ja` (`Id_JA`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_nomination_rencontre` FOREIGN KEY (`Id_Rencontre`) REFERENCES `rencontre` (`Id_Rencontre`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── region ──
DROP TABLE IF EXISTS `region`;
CREATE TABLE `region` (
  `code` varchar(2) NOT NULL,
  `nom` varchar(255) NOT NULL,
  `chef_lieu` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── rencontre ──
DROP TABLE IF EXISTS `rencontre`;
CREATE TABLE `rencontre` (
  `Id_Rencontre` int(11) NOT NULL AUTO_INCREMENT,
  `Date` date NOT NULL,
  `Heure` time NOT NULL,
  `Id_Division` int(11) DEFAULT NULL,
  `Poule` tinyint(11) NOT NULL,
  `Id_EquipeDom` int(11) NOT NULL,
  `Id_EquipeExt` int(11) DEFAULT NULL,
  `Phase` tinyint(1) NOT NULL,
  `Saison` varchar(9) DEFAULT NULL,
  `Journee` tinyint(4) DEFAULT NULL,
  `id_Salle` int(11) DEFAULT NULL,
  `ArbitrageObligatoire` tinyint(1) NOT NULL DEFAULT 1,
  `Commentaire` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`Id_Rencontre`),
  KEY `fk_rencontre_division` (`Id_Division`),
  KEY `fk_rencontre_equipe_dom` (`Id_EquipeDom`),
  KEY `fk_rencontre_equipe_ext` (`Id_EquipeExt`),
  KEY `fk_rencontre_salle` (`id_Salle`),
  CONSTRAINT `fk_rencontre_division` FOREIGN KEY (`Id_Division`) REFERENCES `division` (`Id_Division`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_rencontre_equipe_dom` FOREIGN KEY (`Id_EquipeDom`) REFERENCES `equipe` (`Id_Equipe`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_rencontre_equipe_ext` FOREIGN KEY (`Id_EquipeExt`) REFERENCES `equipe` (`Id_Equipe`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_rencontre_salle` FOREIGN KEY (`id_Salle`) REFERENCES `salle` (`Id_Salle`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=393 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── salle ──
DROP TABLE IF EXISTS `salle`;
CREATE TABLE `salle` (
  `Id_Salle` int(11) NOT NULL AUTO_INCREMENT,
  `Nom` varchar(100) NOT NULL,
  `Adresse` varchar(255) DEFAULT NULL,
  `Id_Laposte` int(11) DEFAULT NULL,
  `Id_Club` int(11) DEFAULT NULL,
  `EstPrincipale` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`Id_Salle`),
  KEY `fk_salle_laposte` (`Id_Laposte`),
  KEY `fk_salle_club` (`Id_Club`),
  CONSTRAINT `fk_salle_club` FOREIGN KEY (`Id_Club`) REFERENCES `club` (`Id_Club`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_salle_laposte` FOREIGN KEY (`Id_Laposte`) REFERENCES `laposte` (`Id_LaPoste`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=278 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── utilisateur ──
DROP TABLE IF EXISTS `utilisateur`;
CREATE TABLE `utilisateur` (
  `Id_Utilisateur` int(11) NOT NULL AUTO_INCREMENT,
  `Login` varchar(50) DEFAULT NULL,
  `Password` varchar(255) DEFAULT NULL,
  `Nom` varchar(50) DEFAULT NULL,
  `Prenom` varchar(50) DEFAULT NULL,
  `Role` varchar(30) DEFAULT NULL,
  `Email_LNTT` varchar(50) DEFAULT NULL,
  `Actif` tinyint(1) DEFAULT 1,
  `Id_Departement` int(11) DEFAULT NULL,
  `ChangeLogin` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`Id_Utilisateur`),
  KEY `fk_utilisateur_departement` (`Id_Departement`) USING BTREE
) ENGINE=MyISAM AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS = 1;