INSERT INTO `messagerie` (`Id_Messagerie`, `Id_Utilisateur`, `Type`, `Sujet`, `Message`) VALUES ('1', '1', 'Disponibilites', 'Arbitrage de la nouvelle phase du championnat', 'Bonjour {PRENOM} {NOM},\n\nCi-joint le lien pour la saisie de vos disponibilités pour les arbitrages du Championnat Phase 1 2026.\n\n{LIEN_LIGUE}//nijac/Nominateur/disponibilite_ja.php?ja={ID_JA}}\n\nCordialement\n\n{UTI_PRENOM}  {UTI_NOM}');
INSERT INTO `messagerie` (`Id_Messagerie`, `Id_Utilisateur`, `Type`, `Sujet`, `Message`) VALUES ('2', '1', 'Rappel dispo', 'Relance : Arbitrage de la nouvelle phase du championnat', 'Bonjour {PRENOM} {NOM},\n\nCi-joint le lien pour la saisie de vos disponibilités pour les arbitrages du Championnat Phase 1 2026.\n\n{LIEN_LIGUE}/nijac/Nominateur/disponibilite_ja.php?ja={ID_JA}}\n\nCordialement\n\n{UTI_PRENOM} {UTI_NOM}');
INSERT INTO `messagerie` (`Id_Messagerie`, `Id_Utilisateur`, `Type`, `Sujet`, `Message`) VALUES ('3', '1', 'Convocation', 'Convocation pour la journée  {JOURNEE} Division : {DIVISION} du Championnat', 'Convocation\n\nNom du JUGE ARBITRE : {NOMPRENOM}\n\nJ\'ai l\'avantage de vous informer que vous êtes désigné(e) pour diriger la rencontre suivante du Championnat de France par Équipes {Sexe}.\n\nJournée n° {JOURNEE}      Division : {DIVISION}    Poule : {POULE}\nOpposant : {DOM} à {EXT}\nle {DATE} à {HEURE}\n\nAdresse : {SALLE_NOM} {SALLE_ADRESSE} {SALLE_CP} {SALLE_VILLE}\n\nNom, PRÉNOM du CORRESPONDANT, {CORR_NOM}\n\n Tél : {CORR_TEL}                               Courriel : {CORR_EMAIL}\n\nVeuillez agréer mes meilleurs sentiments.\n{UTI_PRENOM} {UTI_NOM}');
